import { localConfig } from "./local-config.mjs";
// Run only against local Supabase. Never prints keys or generated passwords.
import { createClient } from "@supabase/supabase-js";
import { execFileSync } from "node:child_process";
import { randomBytes } from "node:crypto";
import { writeFileSync, chmodSync, existsSync, readFileSync } from "node:fs";
const env = localConfig();
if (
  existsSync(".env.local") &&
  !readFileSync(".env.local", "utf8").startsWith(
    "# Generated by seed-local.mjs",
  )
)
  throw new Error(
    "Existing .env.local preserved; move it explicitly before local seeding.",
  );
const url = env.API_URL;
if (!url || !["127.0.0.1", "localhost"].includes(new URL(url).hostname))
  throw new Error("Only local Supabase is allowed.");
const db = createClient(url, env.SERVICE_ROLE_KEY, {
  auth: { persistSession: false },
});
const password = randomBytes(24).toString("base64url");
const institutions = [
  "10000000-0000-4000-8000-000000000001",
  "10000000-0000-4000-8000-000000000002",
];
const users = [
  ["superadmin", "institution_admin", institutions[0]],
  ["admin", "institution_admin", institutions[0]],
  ["referada", "registrar", institutions[0]],
  ["nastavnik", "teacher", institutions[0]],
  ["student", "student", institutions[0]],
  ["student2", "student", institutions[1]],
];
const results = {};
for (const [name, role, institution_id] of users) {
  const email = `${name}@example.test`;
  let { data: existing } = await db.auth.admin.listUsers();
  let user = existing?.users.find((u) => u.email === email);
  if (!user) {
    const invite = await db
      .from("registration_invites")
      .insert({ institution_id, email, role });
    if (invite.error) throw invite.error;
    const created = await db.auth.admin.createUser({
      email,
      password,
      email_confirm: true,
      user_metadata: { full_name: `Test ${name}` },
    });
    if (created.error) throw created.error;
    user = created.data.user;
  } else {
    const updated = await db.auth.admin.updateUserById(user.id, { password });
    if (updated.error) throw updated.error;
  }
  results[name] = { id: user.id, email, password };
}
const superuser = results.superadmin.id;
// Bootstrap privilege is intentionally SQL-only; there is no public API for this operation.
execFileSync(
  "docker",
  [
    "--host=unix:///var/run/docker.sock",
    "exec",
    "-i",
    env.DB_CONTAINER || "supabase_db_svs",
    "psql",
    "-U",
    "postgres",
    "-d",
    "postgres",
    "-v",
    "ON_ERROR_STOP=1",
    "-c",
    `insert into public.superadmins(user_id) values ('${superuser}') on conflict do nothing;`,
  ],
  { stdio: ["ignore", "pipe", "pipe"] },
);
writeFileSync(
  ".env.local",
  `# Generated by seed-local.mjs\nNEXT_PUBLIC_SUPABASE_URL=${url}\nNEXT_PUBLIC_SUPABASE_PUBLISHABLE_KEY=${env.ANON_KEY}\nAUTH_INVITE_SIGNUP_ENABLED=true\nLOCAL_BASE_DOMAIN=svs.test\n`,
  { mode: 0o600 },
);
chmodSync(".env.local", 0o600);
writeFileSync(".local-test-users.json", JSON.stringify(results, null, 2), {
  mode: 0o600,
});
chmodSync(".local-test-users.json", 0o600);
console.log(
  "Local users and .env.local prepared. Credentials: ignored .local-test-users.json (do not commit).",
);
